import json, urllib.request
def holen(u):
    q = urllib.request.Request(u, headers={"User-Agent": "myelith-agentenprobe (https://github.com/crowdedconfusion/Myelith)", "Accept": "application/json"})
    return json.load(urllib.request.urlopen(q, timeout=20))
