soll = {
    "ripgrep": rg["tag_name"].lstrip("v"),
    "ripgrep_datum": rg["published_at"][:10],
    "requests": holen("https://pypi.org/pypi/requests/json")["info"]["version"],
    "serde": holen("https://crates.io/api/v1/crates/serde")["crate"]["max_stable_version"],
}

from pathlib import Path
ist = dict(z.split("=", 1) for z in Path("versionen.txt").read_text(encoding="utf-8").replace("\r", "").split() if "=" in z)
ist = {k.strip(): v.strip().lstrip("v") for k, v in ist.items()}
